from pathlib import Path
import sys

ui_path = Path(sys.argv[1])
vm_path = Path(sys.argv[2])
repo_path = Path(sys.argv[3])

s = ui_path.read_text()

def rep(old, new, count=1):
    global s
    if old not in s:
        raise SystemExit('missing UI anchor: ' + old[:100])
    s = s.replace(old, new, count)

rep('import kotlinx.coroutines.delay\n', 'import kotlinx.coroutines.delay\nimport kotlinx.coroutines.Job\nimport kotlinx.coroutines.launch\n')
rep('import androidx.compose.runtime.remember\n', 'import androidx.compose.runtime.remember\nimport androidx.compose.runtime.rememberCoroutineScope\nimport androidx.compose.runtime.key\n')

rep('''                    onRenamePackage = viewModel::renamePackage,\n                    onMovePackage = viewModel::movePackage,\n                    onToggleCollapsed = viewModel::toggleSectionCollapsed,''', '''                    onRenamePackage = viewModel::renamePackage,\n                    onMovePackage = viewModel::movePackage,\n                    onSetPackageOrder = viewModel::setPackageOrder,\n                    onToggleCollapsed = viewModel::toggleSectionCollapsed,''')

rep('''    onRenamePackage: (Long, String, String) -> Unit,\n    onMovePackage: (Long, String, Int) -> Unit,\n    onToggleCollapsed: (Long) -> Unit,''', '''    onRenamePackage: (Long, String, String) -> Unit,\n    onMovePackage: (Long, String, Int) -> Unit,\n    onSetPackageOrder: (Long, List<String>) -> Unit,\n    onToggleCollapsed: (Long) -> Unit,''')

rep('''                    onEditApp = { pkg -> actionApp = section to pkg },\n                    onMovePackage = { pkg, direction -> onMovePackage(section.id, pkg, direction) }\n                )''', '''                    onEditApp = { pkg -> actionApp = section to pkg },\n                    onSetPackageOrder = { ordered -> onSetPackageOrder(section.id, ordered) }\n                )''')

rep('''    onToggleCollapsed: () -> Unit,\n    onEditApp: (String) -> Unit,\n    onMovePackage: (String, Int) -> Unit\n) {''', '''    onToggleCollapsed: () -> Unit,\n    onEditApp: (String) -> Unit,\n    onSetPackageOrder: (List<String>) -> Unit\n) {''')

rep('''                        showLabels = showLabels,\n                        onEditApp = onEditApp,\n                        onMovePackage = onMovePackage\n                    )''', '''                        showLabels = showLabels,\n                        onEditApp = onEditApp,\n                        onCommitOrder = { visibleOrder ->\n                            val hiddenPackages = section.packages.filterNot { it in visibleOrder }\n                            onSetPackageOrder(visibleOrder + hiddenPackages)\n                        }\n                    )''')

start = s.index('@Composable\nprivate fun AppGrid(')
end = s.index('@Composable\nprivate fun AppTile(', start)
new_grid = '''@Composable\nprivate fun AppGrid(\n    section: AppSection,\n    appMap: Map<String, InstalledApp>,\n    columns: Int,\n    showLabels: Boolean,\n    onEditApp: (String) -> Unit,\n    onCommitOrder: (List<String>) -> Unit\n) {\n    val safeColumns = columns.coerceIn(4, 6)\n    var localOrder by remember(section.id) { mutableStateOf(section.packages) }\n    var activeDrag by remember(section.id) { mutableStateOf<String?>(null) }\n\n    LaunchedEffect(section.packages) {\n        if (activeDrag == null && localOrder != section.packages) {\n            localOrder = section.packages\n        }\n    }\n\n    fun moveLocal(pkg: String, direction: Int) {\n        val from = localOrder.indexOf(pkg)\n        if (from < 0 || localOrder.isEmpty()) return\n        val to = (from + direction).coerceIn(0, localOrder.lastIndex)\n        if (to == from) return\n        localOrder = localOrder.toMutableList().apply {\n            val item = removeAt(from)\n            add(to, item)\n        }\n    }\n\n    Column(verticalArrangement = Arrangement.spacedBy(6.dp)) {\n        localOrder.chunked(safeColumns).forEach { rowApps ->\n            Row(modifier = Modifier.fillMaxWidth()) {\n                rowApps.forEach { pkg ->\n                    key(pkg) {\n                        val app = appMap[pkg]\n                        val label = section.aliases[pkg].orEmpty().ifBlank { app?.label ?: "حذف‌شده" }\n                        Box(modifier = Modifier.weight(1f), contentAlignment = Alignment.TopCenter) {\n                            AppTile(\n                                packageName = pkg,\n                                label = label,\n                                showLabel = showLabels,\n                                columns = safeColumns,\n                                onMove = { direction -> moveLocal(pkg, direction) },\n                                onLongPress = { onEditApp(pkg) },\n                                onDragStateChange = { dragging ->\n                                    if (dragging) {\n                                        activeDrag = pkg\n                                    } else if (activeDrag == pkg) {\n                                        activeDrag = null\n                                        if (localOrder != section.packages) onCommitOrder(localOrder)\n                                    }\n                                }\n                            )\n                        }\n                    }\n                }\n                repeat(safeColumns - rowApps.size) { Spacer(Modifier.weight(1f)) }\n            }\n        }\n    }\n}\n\n'''
s = s[:start] + new_grid + s[end:]

start = s.index('@Composable\nprivate fun AppTile(')
end = s.index('@Composable\nprivate fun AppQuickActionsDialog', start)
new_tile = '''@Composable\nprivate fun AppTile(\n    packageName: String,\n    label: String,\n    showLabel: Boolean,\n    columns: Int,\n    onMove: (Int) -> Unit,\n    onLongPress: () -> Unit,\n    onDragStateChange: (Boolean) -> Unit\n) {\n    val context = LocalContext.current\n    val density = LocalDensity.current\n    val haptic = LocalHapticFeedback.current\n    val gestureScope = rememberCoroutineScope()\n    val tileTint = remember(packageName) { appAccent(packageName) }\n    var dragX by remember(packageName) { mutableFloatStateOf(0f) }\n    var dragY by remember(packageName) { mutableFloatStateOf(0f) }\n    var dragging by remember(packageName) { mutableStateOf(false) }\n    var moved by remember(packageName) { mutableStateOf(false) }\n    var actionJob by remember(packageName) { mutableStateOf<Job?>(null) }\n    var actionShown by remember(packageName) { mutableStateOf(false) }\n    val stepThreshold = with(density) { 22.dp.toPx() }\n    val cancelMenuDistance = with(density) { 7.dp.toPx() }\n    val maxOffset = with(density) { 50.dp.toPx() }\n\n    fun resetGesture() {\n        actionJob?.cancel()\n        actionJob = null\n        if (dragging) onDragStateChange(false)\n        dragX = 0f\n        dragY = 0f\n        dragging = false\n        moved = false\n        actionShown = false\n    }\n\n    Column(\n        modifier = Modifier\n            .zIndex(if (dragging) 8f else 0f)\n            .graphicsLayer {\n                translationX = dragX.coerceIn(-maxOffset, maxOffset)\n                translationY = dragY.coerceIn(-maxOffset, maxOffset)\n                scaleX = if (dragging) 1.09f else 1f\n                scaleY = if (dragging) 1.09f else 1f\n                alpha = if (dragging) 0.97f else 1f\n            }\n            .clip(RoundedCornerShape(15.dp))\n            .pointerInput(packageName, columns) {\n                detectDragGesturesAfterLongPress(\n                    onDragStart = {\n                        dragging = true\n                        moved = false\n                        actionShown = false\n                        onDragStateChange(true)\n                        haptic.performHapticFeedback(HapticFeedbackType.LongPress)\n                        actionJob?.cancel()\n                        actionJob = gestureScope.launch {\n                            delay(800L)\n                            if (dragging && !moved && !actionShown) {\n                                actionShown = true\n                                haptic.performHapticFeedback(HapticFeedbackType.LongPress)\n                                onLongPress()\n                            }\n                        }\n                    },\n                    onDragCancel = { resetGesture() },\n                    onDragEnd = { resetGesture() },\n                    onDrag = { change, amount ->\n                        if (actionShown) return@detectDragGesturesAfterLongPress\n                        change.consume()\n                        dragX += amount.x\n                        dragY += amount.y\n\n                        if (!moved && (abs(dragX) >= cancelMenuDistance || abs(dragY) >= cancelMenuDistance)) {\n                            moved = true\n                            actionJob?.cancel()\n                            actionJob = null\n                        }\n\n                        while (abs(dragX) >= stepThreshold) {\n                            onMove(if (dragX < 0f) 1 else -1)\n                            dragX += if (dragX < 0f) stepThreshold else -stepThreshold\n                        }\n                        while (abs(dragY) >= stepThreshold) {\n                            onMove(if (dragY > 0f) columns else -columns)\n                            dragY += if (dragY > 0f) -stepThreshold else stepThreshold\n                        }\n                    }\n                )\n            }\n            .combinedClickable(onClick = { launchPackage(context, packageName) })\n            .padding(horizontal = 2.dp, vertical = 6.dp),\n        horizontalAlignment = Alignment.CenterHorizontally\n    ) {\n        Surface(\n            shape = RoundedCornerShape(16.dp),\n            color = tileTint.copy(alpha = if (dragging) 0.19f else 0.09f),\n            border = BorderStroke(1.dp, tileTint.copy(alpha = if (dragging) 0.45f else 0.17f)),\n            shadowElevation = if (dragging) 12.dp else 1.dp\n        ) {\n            CachedAppIcon(packageName, label, Modifier.padding(6.dp), 42)\n        }\n        if (showLabel) {\n            Spacer(Modifier.height(5.dp))\n            Text(\n                label,\n                maxLines = 1,\n                overflow = TextOverflow.Ellipsis,\n                fontSize = 10.sp,\n                textAlign = TextAlign.Center,\n                modifier = Modifier.fillMaxWidth()\n            )\n        }\n    }\n}\n\n'''
s = s[:start] + new_tile + s[end:]

s = s.replace('"نگه‌داشتن بدون حرکت: ویرایش / تغییر نام / حذف — نگه‌داشتن و کشیدن: جابه‌جایی روان",', '"برای جابه‌جایی نگه‌دار و بکش؛ برای ویرایش، حدود یک تا دو ثانیه بدون حرکت نگه‌دار.",', 1)
ui_path.write_text(s)

vm = vm_path.read_text()
anchor = '''    fun movePackage(sectionId: Long, packageName: String, direction: Int) = launch {\n        stateRepository.movePackage(sectionId, packageName, direction)\n    }\n'''
if anchor not in vm:
    raise SystemExit('missing VM anchor')
vm = vm.replace(anchor, anchor + '''\n    fun setPackageOrder(sectionId: Long, packages: List<String>) = launch {\n        stateRepository.setPackageOrder(sectionId, packages)\n    }\n''', 1)
vm_path.write_text(vm)

repo = repo_path.read_text()
anchor = '''    suspend fun movePackage(sectionId: Long, packageName: String, direction: Int) = updateSections { current ->\n        current.map { section ->\n            if (section.id != sectionId) return@map section\n            val from = section.packages.indexOf(packageName)\n            if (from < 0) return@map section\n            val to = (from + direction).coerceIn(0, section.packages.lastIndex)\n            if (to == from) return@map section\n            val reordered = section.packages.toMutableList().apply {\n                val item = removeAt(from)\n                add(to, item)\n            }\n            section.copy(packages = reordered)\n        }\n    }\n'''
if anchor not in repo:
    raise SystemExit('missing repository anchor')
repo = repo.replace(anchor, anchor + '''\n    suspend fun setPackageOrder(sectionId: Long, packages: List<String>) = updateSections { current ->\n        current.map { section ->\n            if (section.id != sectionId) return@map section\n            val allowed = section.packages.toSet()\n            val ordered = packages.filter { it in allowed }.distinct()\n            val missing = section.packages.filterNot { it in ordered }\n            section.copy(packages = ordered + missing)\n        }\n    }\n''', 1)
repo_path.write_text(repo)

print('AppDeck V7 patch applied')
